"""Independent brute-force reference for the periodic envelope (small cases)."""
import heapq, random, sys
from math import gcd
sys.path.insert(0, '/workspace/submission')
import para, topo, algo


def period(T, S, Q):
    return (Q * S) // gcd(T, Q * S)


def brute(fb, cal, g, horizon):
    """Time expanded lexicographic Dijkstra over absolute boundaries 0..horizon."""
    N = fb['n']; T = fb['interval_ns']; S = fb['slice_ns']; O = fb['offset_ns']
    slices = fb['slices']; Q = len(slices); P = period(T, S, Q)
    links = fb['links']
    # effective rates
    eff = [[fb['drift_ppb'][i]] * P for i in range(N)]
    for (node, a, b, x) in fb['heat']:
        for p in range(a, b):
            eff[node][p] += x
    anchored = [[False] * N for _ in range(P)]
    for (node, a, b) in fb['anchors']:
        for p in range(a, b):
            anchored[p][node] = True
    black = [[False] * P for _ in range(len(links))]
    for (l, a, b) in fb['blackouts']:
        for p in range(a, b):
            black[l][p] = True
    jit = cal.jitter
    H = cal.H

    def cal_info(p):
        t = O + p * T
        return (t // S) % Q, t % S

    INF = None
    best = {}
    heap = []
    for t in range(horizon + 1):
        p = t % P
        for i in range(N):
            if anchored[p][i]:
                best[(t, i)] = (0, 0)
                heap.append((0, 0, t, i))
    heapq.heapify(heap)
    while heap:
        c, a, t, i = heapq.heappop(heap)
        if best.get((t, i)) != (c, a):
            continue
        # waiting
        if t + 1 <= horizon:
            nc = (c + eff[i][t % P] * T, a + 1)
            k = (t + 1, i)
            if best.get(k) is None or nc < best[k]:
                best[k] = nc
                heapq.heappush(heap, (nc[0], nc[1], t + 1, i))
        p = t % P
        sl, rho = cal_info(p)
        for l in slices[sl]:
            lk = links[l]
            for d in (0, 1):
                if d == 0:
                    src, dst = lk['ends'][0], lk['ends'][1]
                    delay = lk['delay_ns'][0]; q = lk['defer_rounds'][0]
                else:
                    src, dst = lk['ends'][1], lk['ends'][0]
                    delay = lk['delay_ns'][1]; q = lk['defer_rounds'][1]
                if src[0] != i:
                    continue
                if rho < g or rho + delay + g > S:
                    continue
                k = -(-delay // T)
                if any(black[l][(t + j) % P] for j in range(k)):
                    continue
                age = k + q
                tt = t + age
                if tt > horizon:
                    continue
                kk = t + k
                ag = eff[dst[0]][(kk - 1) % P] * (kk * T - (t * T + delay - t * T) - 0)
                ag = eff[dst[0]][(kk - 1) % P] * (kk * T - delay)
                for rr in range(kk, kk + q):
                    ag += eff[dst[0]][rr % P] * T
                cost = c + H[src[2]][dst[2]] + ag
                nc = (cost, a + age)
                key = (tt, dst[0])
                if best.get(key) is None or nc < best[key]:
                    best[key] = nc
                    heapq.heappush(heap, (nc[0], nc[1], tt, dst[0]))
    return best, P, N, eff


def envelope(fb, cal, g):
    fab = topo.Fabric(fb, cal)
    peaks, sel, res = None, None, None
    best, prevv, prevk = algo.run_dijkstra(fab, g)
    peak, warm = algo.summarise(fab, best)
    B = [None] * fab.V; A = [None] * fab.V
    for v in range(fab.V):
        if best[v] is not None:
            B[v] = best[v] >> topo.AGE_SHIFT
            A[v] = best[v] & topo.AGE_MASK
    return fab, B, A, peak, warm


def check(fb, cal, g, extra_cycles=3, verbose=False):
    fab, B, A, peak, warm = envelope(fb, cal, g)
    P = fab.P; N = fab.N
    if warm is None:
        warm = 0
    horizon = (max(warm, 0) + extra_cycles + 1) * P + P
    best, _, _, eff = brute(fb, cal, g, horizon)
    ok = True
    # 1. eventual agreement
    for t in range(horizon - P + 1, horizon + 1):
        p = t % P
        for i in range(N):
            v = p * N + i
            got = best.get((t, i))
            want = None if B[v] is None else (B[v], A[v])
            if got != want:
                ok = False
                print('MISMATCH eventual t=%d i=%d got=%s want=%s' % (t, i, got, want))
    # 2. warmup exactness
    def cycle_ok(k):
        for t in range(k * P, (k + 1) * P):
            p = t % P
            for i in range(N):
                v = p * N + i
                got = best.get((t, i))
                want = None if B[v] is None else (B[v], A[v])
                if got != want:
                    return False
        return True
    if not cycle_ok(warm):
        ok = False
        print('MISMATCH warmup cycle %d not attained' % warm)
    if warm > 0 and cycle_ok(warm - 1):
        ok = False
        print('MISMATCH warmup %d not minimal' % warm)
    # 3. peak
    if peak is not None:
        mp = 0
        for p in range(P):
            for i in range(N):
                v = p * N + i
                if B[v] is None:
                    mp = None
                    break
                mp = max(mp, B[v] + eff[i][p] * fb['interval_ns'])
            if mp is None:
                break
        if mp != peak:
            ok = False
            print('MISMATCH peak %s != %s' % (peak, mp))
    return ok
